// This package is generated by scripts/build-wasm.mjs before Vite starts.
// @ts-ignore wasm-pack generates this module as part of the Rust build.
import init, { process_image, process_pdf } from '../rust/core/pkg/projectpdf_core.js';

type WorkerFile = { name: string; bytes: ArrayBuffer };
type WorkerRequest = { id: number; tool: string; files: WorkerFile[]; options: Record<string, unknown> };
type WasmOutput = {
  name: string;
  mime: string;
  bytes: Uint8Array;
  message?: string;
  quality?: number;
  paletteColors?: number;
  compressionLevel?: number;
};

const IMAGE_TOOLS = new Set([
  'Compress Image',
  'Change Signature Width & Height',
  'Change Photo Width & Height',
  'Convert Photo to JPG',
  'Crop Photo',
  'Make Passport Size Photo',
  'Add Name & Date on Photo',
]);

let initialized: Promise<unknown> | undefined;
const workerScope = self as unknown as {
  addEventListener(type: 'message', listener: (event: MessageEvent<WorkerRequest>) => void): void;
  postMessage(message: unknown, transfer: Transferable[]): void;
};

workerScope.addEventListener('message', (event) => {
  const request = event.data;
  void (async () => {
    try {
      initialized ??= init();
      await initialized;
      const output = IMAGE_TOOLS.has(request.tool)
        ? [process_image(request.tool, request.files[0].name, new Uint8Array(request.files[0].bytes), request.options)]
        : process_pdf(
          request.tool,
          request.files.map((file) => file.name),
          request.files.map((file) => new Uint8Array(file.bytes)),
          request.options,
        ) as WasmOutput[];
      const outputs = Array.isArray(output) ? output : [output];
      const transfers = outputs.map((item) => item.bytes.buffer as ArrayBuffer);
      workerScope.postMessage({ id: request.id, outputs }, transfers);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      workerScope.postMessage({ id: request.id, error: message }, []);
    }
  })();
});
